return items.map((item) => {
  const currentStock = Number(item.json.CurrentStock);
  const averageDailySales = Number(item.json.AverageDailySales);
  const supplierLeadDays = Number(item.json.SupplierLeadDays);
  const stockCoverageDays = Number((currentStock / averageDailySales).toFixed(1));

  let riskLevel = 'Low';
  let priorityScore = 25;

  if (stockCoverageDays <= supplierLeadDays) {
    riskLevel = 'High';
    priorityScore = 90;
  } else if (stockCoverageDays <= supplierLeadDays * 1.5) {
    riskLevel = 'Medium';
    priorityScore = 60;
  }

  return {
    json: {
      ...item.json,
      CurrentStock: currentStock,
      AverageDailySales: averageDailySales,
      SupplierLeadDays: supplierLeadDays,
      UnitPrice: Number(item.json.UnitPrice),
      StockCoverageDays: stockCoverageDays,
      RiskLevel: riskLevel,
      PriorityScore: priorityScore
    }
  };
});

return items.map((item) => ({
  json: {
    ...item.json,
    aiInput: `Review ${item.json.Brand} ${item.json.Model}. Stock coverage is ${item.json.StockCoverageDays} days and supplier lead time is ${item.json.SupplierLeadDays} days. Risk is ${item.json.RiskLevel}. Explain the priority and recommend a practical inventory action.`
  }
}));

return items.map((item) => {
  const content = item.json.text ?? item.json.message?.content ?? item.json.content;

  if (!content) {
    throw new Error('The AI response did not include any content.');
  }

  return {
    json: typeof content === 'string' ? JSON.parse(content) : content
  };
});
